import { createCollection } from 'qortex-resource';

const todos = createCollection<Todo>({
  getId: (t) => t.id,
  initialData: [],
});

todos.addOne({ id: '1', title: 'Ship alpha', done: false });

const row = todos.getResource('1');
row.set('title', 'Ship alpha docs');
await row.save(); // updates collection item
